parameters.jsCode:
const body = $input.first().json.body || $input.first().json;

const authorId = body.author_id || body.authorId;
if (!authorId) {
  throw new Error('Missing required field: author_id');
}

const requestId = body.request_id || `${authorId}-${Date.now()}`;
const triggeredBy = body.triggered_by || 'admin';
const triggerSource = body.trigger_source || 'manual';

const authorData = body.author_data || (body.books ? body : null);
const hasFullPayload = Boolean(authorData && Array.isArray(authorData.books) && authorData.books.length > 0);

return [{
  json: {
    author_id: authorId,
    request_id: requestId,
    triggered_by: triggeredBy,
    trigger_source: triggerSource,
    has_full_payload: hasFullPayload,
    author_data: authorData || {},
    received_at: new Date().toISOString()
  }
}];

const item = $input.first().json;
let author = item.author_data || item.response || item;

const books = author.books || [];
let totalEarned = 0;
let totalPaid = 0;
let totalPending = 0;
let publishedCount = 0;
let inProductionCount = 0;

const booksSummary = books.map(b => {
  const earned = Number(b.total_royalty_earned || b.royalty_earned || 0);
  const paid = Number(b.royalty_paid || 0);
  const pending = Number(b.royalty_pending || (earned - paid));

  totalEarned += earned;
  totalPaid += paid;
  totalPending += pending;

  if (b.status === 'Published & Live') {
    publishedCount++;
  } else {
    inProductionCount++;
  }

  return {
    book_id: b.book_id || 'BK',
    title: b.title,
    isbn: b.isbn || 'Pending',
    status: b.status,
    copies_sold: b.total_copies_sold || b.copies_sold || 0,
    royalty_earned: earned,
    royalty_paid: paid,
    royalty_pending: pending,
    last_payout: b.last_royalty_payout_date || 'None',
    available_on: Array.isArray(b.available_on) ? b.available_on.join(', ') : (b.available_on || 'Not yet live')
  };
});

return [{
  json: {
    author_id: item.author_id || author.author_id,
    request_id: item.request_id || `${item.author_id}-${Date.now()}`,
    name: author.name || author.author_name || 'Author',
    email: author.email || 'author@bookleaf.com',
    city: author.city || 'India',
    total_books: books.length,
    published_count: publishedCount,
    in_production_count: inProductionCount,
    total_royalty_earned: totalEarned,
    total_royalty_paid: totalPaid,
    total_royalty_pending: totalPending,
    books_summary: booksSummary,
    has_pending_royalty: totalPending > 0,
    has_in_production: inProductionCount > 0
  }
}];

